import fire

from lmdeploy import GenerationConfig, PytorchEngineConfig, TurbomindEngineConfig, pipeline
from lmdeploy.archs import autoget_backend


def input_prompt():
    """Input a prompt in the consolo interface."""
    print('\ndouble enter to end input >>> ', end='')
    sentinel = ''  # ends when this string is seen
    return '\n'.join(iter(input, sentinel))


def build_pipe(model_path, backend, **kwargs):
    engine_config = None
    if kwargs.get('enable_prefix_caching', False):
        print('interactive chat cannot be used when prefix caching is enabled')
        exit(-1)
    if backend == 'turbomind':
        engine_config = TurbomindEngineConfig()
        for key, value in kwargs.items():
            if hasattr(TurbomindEngineConfig, key):
                setattr(engine_config, key, value)
    else:
        engine_config = PytorchEngineConfig()
        for key, value in kwargs.items():
            if hasattr(PytorchEngineConfig, key):
                setattr(engine_config, key, value)
        if kwargs.get('adapters', None):
            from .utils import get_lora_adapters
            adapters = get_lora_adapters(kwargs['adapters'])
            engine_config.adapters = adapters
    # set chat template config
    chat_template = kwargs.get('chat_template', None)
    chat_template_config = None
    if chat_template:
        from .utils import get_chat_template
        chat_template_config = get_chat_template(chat_template, model_path)
    pipe = pipeline(model_path,
                    backend_config=engine_config,
                    chat_template_config=chat_template_config,
                    log_level='ERROR',
                    **kwargs)
    return pipe


def build_gen_config(**kwargs):
    gen_config = GenerationConfig(do_sample=True, max_new_tokens=4096)
    for key, value in kwargs.items():
        if hasattr(GenerationConfig, key):
            setattr(gen_config, key, value)
    return gen_config


def get_adapter_name(adapters=None, **kwargs):
    if adapters is None:
        return None
    from .utils import get_lora_adapters
    adapters = get_lora_adapters(adapters)
    return list(adapters.keys())[0]


def main(model_path, backend, **kwargs):
    if backend != 'pytorch':
        # set auto backend mode
        backend = autoget_backend(model_path)

    pipe = build_pipe(model_path, backend, **kwargs)
    gen_config = build_gen_config(**kwargs)
    adapter_name = get_adapter_name(**kwargs)

    quit = False
    while not quit:
        with pipe.session(gen_config) as sess:
            while True:
                try:
                    prompt = input_prompt()
                except KeyboardInterrupt:
                    quit = True
                    break
                if prompt == 'end':
                    sess.close()
                    break
                if prompt == 'exit':
                    quit = True
                    break
                if prompt.strip() == '':
                    continue
                resps = sess(prompt, adapter_name=adapter_name)
                try:
                    for resp in resps:
                        print(resp.text, end='', flush=True)
                except KeyboardInterrupt:
                    sess.stop()
    else:
        print('exiting...')


if __name__ == '__main__':
    fire.Fire(main)

import torch
from PIL import Image
from .base import BaseModel
from ..smp import *
from ..dataset import DATASET_TYPE
from io import BytesIO
import base64
from mimetypes import guess_type


class llama4(BaseModel):

    INSTALL_REQ = False
    INTERLEAVE = True

    def __init__(self, model_path="meta-llama/Llama-4-Scout-17B-16E-Instruct", **kwargs):
        try:
            from transformers import AutoProcessor, Llama4ForConditionalGeneration
        except Exception as e:
            logging.critical('Please install transformers>=4.51.0 before using llama4.')
            raise e
        self.generate_kwargs = dict(
            max_new_tokens=kwargs.get('max_new_tokens', 4096),
            top_p=kwargs.get('top_p', 0.001),
            top_k=kwargs.get('top_k', 1),
            temperature=kwargs.get('temperature', 0.01),
            repetition_penalty=kwargs.get('repetition_penalty', 1.0),
        )
        self.system_prompt = kwargs.get('system_prompt', None)

        self.use_vllm = kwargs.get('use_vllm', False)
        self.use_lmdeploy = kwargs.get('use_lmdeploy', False)
        assert self.use_vllm + self.use_lmdeploy <= 1, "You can only set one flag between `use_vllm` and `use_lmdeploy` to True"  # noqa: E501

        self.limit_mm_per_prompt = 10  # vLLM support max 10 images per prompt for Llama 4
        if self.use_vllm:
            from vllm import LLM, SamplingParams
            # Set tensor_parallel_size [8, 4, 2, 1] based on the number of available GPUs
            gpu_count = torch.cuda.device_count()
            if gpu_count >= 8:
                tp_size = 8
            elif gpu_count >= 4:
                tp_size = 4
            elif gpu_count >= 2:
                tp_size = 2
            else:
                tp_size = 1
            logging.info(
                f'Using vLLM for Llama4 inference with {tp_size} GPUs (available: {gpu_count})'
            )
            import os
            if os.environ.get('VLLM_WORKER_MULTIPROC_METHOD') != 'spawn':
                logging.warning(
                    'VLLM_WORKER_MULTIPROC_METHOD is not set to spawn.'
                    'Use \'export VLLM_WORKER_MULTIPROC_METHOD=spawn\' to avoid potential multi-process issues'
                )
            self.llm = LLM(
                model=model_path,
                max_num_seqs=4,
                max_model_len=32768,
                limit_mm_per_prompt={"image": self.limit_mm_per_prompt},
                tensor_parallel_size=tp_size,
                gpu_memory_utilization=kwargs.get("gpu_utils", 0.9),
            )
            # export VLLM_WORKER_MULTIPROC_METHOD=spawn

        elif self.use_lmdeploy:
            from lmdeploy import TurbomindEngineConfig, pipeline, ChatTemplateConfig
            num_gpus = torch.cuda.device_count()
            self.model = pipeline(
                model_path,
                backend_config=TurbomindEngineConfig(session_len=32768, cache_max_entry_count=0.1, tp=num_gpus)
            )
            torch.cuda.set_device(0)
            self.device = 'cuda'

        else:
            self.model = Llama4ForConditionalGeneration.from_pretrained(
                model_path,
                attn_implementation="flash_attention_2",
                device_map="auto",
                torch_dtype=torch.bfloat16,
            )

        self.device = 'cuda'
        self.processor = AutoProcessor.from_pretrained(model_path)
        self.model_name = model_path

    def use_custom_prompt(self, dataset):
        if dataset is None:
            return False
        if listinstr(['AI2D', 'MMMU', 'MathVista', 'ChartQA', 'DocVQA'], dataset):
            # For Certain dataset we use custom prompt
            return True
        else:
            return False

    def build_prompt(self, line, dataset=None):
        assert self.use_custom_prompt(dataset)
        assert dataset is None or isinstance(dataset, str)
        tgt_path = self.dump_image(line, dataset)
        question = line['question']
        options = {
            cand: line[cand]
            for cand in string.ascii_uppercase
            if cand in line and not pd.isna(line[cand])
        }
        if listinstr(['MMMU'], dataset):
            self.kwargs['max_new_tokens'] = 2048
            options = '\n'.join([f'{key}. {item}' for key, item in options.items()])
            prompt = (
                f'Look at the image carefully and solve the following question step-by-step. '
                f'Question: {question} Options: {options} Indicate the correct answer at the end.'
            )
            for i in range(len(tgt_path)):
                prompt = prompt.replace(f'<image {i + 1}>', '')
        elif listinstr(['MathVista'], dataset):
            self.kwargs['max_new_tokens'] = 2048
            prompt = f'{question}'
        elif listinstr(['DocVQA'], dataset):
            self.kwargs['max_new_tokens'] = 512
            prompt = (
                f'Read the text in the image carefully and answer the question '
                f'with the text as seen exactly in the image. '
                f'For yes/no questions, just respond Yes or No. '
                f'If the answer is numeric, just respond with the number and nothing else. '
                f'If the answer has multiple words, just respond with the words and absolutely nothing else. '
                f'Never respond in a sentence or a phrase.\n Question: {question}'
            )
        else:
            raise NotImplementedError(f'Dataset {dataset}) not supported.')

        message = [dict(type='text', value=prompt)]
        message.extend([dict(type='image', value=s) for s in tgt_path])
        return message

    def encode_image(self, image_path):
        mime_type, _ = guess_type(image_path)
        if mime_type is None:
            mime_type = "image/jpeg"
        image_format = mime_type.split("/")[-1].upper() if mime_type else "JPEG"
        image = Image.open(image_path)
        # Handle the alpha channel
        if image.mode == "RGBA":
            image = self._rgba_to_rgb(image)

        encoded_image = self._encode_image(image, image_format)

        return encoded_image

    def _encode_image(self, image, image_format):
        with BytesIO() as output:
            image.convert("RGB").save(output, format=image_format)
            base64_encoded_data = base64.b64encode(output.getvalue()).decode("utf-8")
        return base64_encoded_data

    @staticmethod
    def _rgba_to_rgb(image):
        background = Image.new("RGBA", image.size, (255, 255, 255, 255))
        return Image.alpha_composite(background, image).convert("RGB")

    def message_to_promptimg(self, message, dataset=None):
        processed_message = []
        for item in message:
            if item['type'] == 'text':
                processed_message.append({
                    "type": "text",
                    "text": f"{item['value']}"
                })
            elif item['type'] == 'image':
                image_path = item['value']
                encoded_image = self.encode_image(image_path)
                processed_message.append({
                    "type": "image",
                    "url": f"{encoded_image}",
                })
        return processed_message

    def generate_inner_transformers(self, message, dataset=None):
        prompt = self.message_to_promptimg(message, dataset=dataset)
        messages = [
            {'role': 'user', 'content': prompt}
        ]
        inputs = self.processor.apply_chat_template(
            messages,
            add_generation_prompt=True,
            tokenize=True,
            return_dict=True,
            return_tensors="pt",
        ).to(self.model.device)
        max_new_tokens = 8192
        outputs = self.model.generate(**inputs, max_new_tokens=max_new_tokens)
        generated_text = self.processor.batch_decode(
            outputs[:, inputs["input_ids"].shape[-1]:]
        )[0]
        if generated_text.endswith("<|eot|>"):
            generated_text = generated_text[:-7]
        return generated_text

    def message_to_promptimg_vllm(self, message, dataset=None):
        processed_message = []
        images = []
        num_images = 0
        for item in message:
            if item['type'] == 'text':
                processed_message.append({
                    "type": "text",
                    "text": item['value']
                })
            elif item['type'] == 'image':
                if num_images < self.limit_mm_per_prompt:
                    image_path = item['value']
                    encoded_image = self.encode_image(image_path)
                    image = Image.open(BytesIO(base64.b64decode(encoded_image)))
                    image.load()
                    processed_message.append({
                        "type": "image",
                        "url": "",
                    })
                    images.append(image)
                    num_images += 1
        if num_images >= self.limit_mm_per_prompt:
            logging.warning(
                f"Number of images exceeds the limit of {self.limit_mm_per_prompt}."
                f"Only the first {self.limit_mm_per_prompt} images will be used."
            )
        return processed_message, images

    def generate_inner_vllm(self, message, dataset=None):
        from vllm import LLM, SamplingParams
        prompt, images = self.message_to_promptimg_vllm(message, dataset=dataset)
        messages = [
            {'role': 'user', 'content': prompt}
        ]
        prompt = self.processor.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=True
        )
        sampling_params = SamplingParams(temperature=self.generate_kwargs['temperature'],
                                         max_tokens=self.generate_kwargs['max_new_tokens'])
        outputs = self.llm.generate(
            {
                "prompt": prompt,
                "multi_modal_data": {
                    "image": images
                },
            },
            sampling_params=sampling_params
        )

        for o in outputs:
            generated_text = o.outputs[0].text

        if generated_text.endswith("<|eot|>"):
            generated_text = generated_text[:-7]  # 删除末尾的<|eot|>

        return generated_text

    def generate_inner_lmdeploy(self, message, dataset=None):
        from lmdeploy import GenerationConfig
        gen_config = GenerationConfig(
            max_new_tokens=self.generate_kwargs['max_new_tokens'],
            top_p=self.generate_kwargs['top_p'],
            top_k=self.generate_kwargs['top_k'],
            temperature=self.generate_kwargs['temperature'],
            repetition_penalty=self.generate_kwargs['repetition_penalty'],
        )
        gen_config.random_seed = None
        messages_list = self.message_to_lmdeploy(message, system_prompt=self.system_prompt)
        assert len(messages_list) == 1
        response = self.model(messages_list, gen_config=gen_config)[0]
        response = response.text
        return response

    def generate_inner(self, message, dataset=None):
        if self.use_vllm:
            return self.generate_inner_vllm(message, dataset=dataset)
        elif self.use_lmdeploy:
            return self.generate_inner_lmdeploy(message, dataset=dataset)
        else:
            return self.generate_inner_transformers(message, dataset=dataset)

import os
import sys
import os.path as osp
import torch
from ..smp import *


def get_gpu_num(model_name):
    model_name = model_name.lower()
    kws = {
        8: ['65b', '70b'],
        4: ['30b', '33b', '35b', '40b'],
        2: ['13b', '14b', '20b', '8b'],
        1: ['6b', '7b', 'moss'],
    }
    for k in [8, 4, 2, 1]:
        for keyword in kws[k]:
            if keyword in model_name:
                return k
    return 8


validated_llms = [
    'internlm/internlm-chat-7b', 'internlm/internlm-chat-7b-8k', 'internlm/internlm-chat-20b',
    'Qwen/Qwen-7B-Chat', 'Qwen/Qwen-14B-Chat',
    'THUDM/chatglm2-6b', 'THUDM/chatglm2-6b-32k', 'THUDM/chatglm3-6b', 'THUDM/chatglm3-6b-32k',
    'baichuan-inc/Baichuan2-7B-Chat', 'baichuan-inc/Baichuan2-13B-Chat',
    'lmsys/vicuna-7b-v1.5', 'lmsys/vicuna-13b-v1.5',
    'meta-llama/Llama-2-7b-chat-hf',
    'meta-llama/Llama-3.1-8B-Instruct'
]
Auto_model = ['chatglm']


class HFChatModel:

    def _get_context_length(self, model, model_path):
        # By default, we use model.config.seq_length
        model_path = model_path.lower()
        if 'baichuan' in model_path:
            context_window = model.config.model_max_length
        elif 'internlm' in model_path or 'llama' in model_path:
            context_window = model.config.max_position_embeddings
        elif 'vicuna' in model_path:
            context_window = model.generation_config.max_length
        else:
            # chatglm & qwen
            context_window = model.config.seq_length
        return context_window

    def _get_context_length_robust(self, model, model_path):
        try:
            context_window = self._get_context_length(model, model_path)
            return context_window
        except Exception as err:
            self.logger.critical(f'{type(err)}: {err}')
            self.logger.critical(
                'Failed to extract context_window information from config / generation_config. '
                'Please read the above code and check if the logic works for you model path'
            )
            raise NotImplementedError

    def __init__(self,
                 model_path,
                 system_prompt: str = None,
                 **kwargs):

        self.logger = get_logger('HFChatModel')
        if 'vicuna' in model_path.lower() or 'llama' in model_path.lower():
            try:
                from fastchat.model import get_conversation_template
            except Exception as err:
                self.logger.critical('Please install fastchat first to use vicuna. ')
                raise err

        self.explicit_device = kwargs.pop('device', None)
        if self.explicit_device is None:
            # If CUDA_VISIBLE_DEVICES is not properly set
            if 'CUDA_VISIBLE_DEVICES' not in os.environ or os.environ['CUDA_VISIBLE_DEVICES'] == '0,1,2,3,4,5,6,7':
                num_gpu = get_gpu_num(model_path)
                gpu_offset = kwargs.pop('gpu_offset', 0)
                cuda_visible_devices = ','.join([str(i) for i in range(gpu_offset, gpu_offset + num_gpu)])
                os.environ['CUDA_VISIBLE_DEVICES'] = cuda_visible_devices

        from transformers import AutoTokenizer, AutoModelForCausalLM, AutoModel

        if model_path not in validated_llms:
            self.logger.warning(f'{model_path} not in validated LLMs, may have inference troubles. ')

        self.model_path = model_path
        if listinstr(Auto_model, model_path):
            LoadModel = AutoModel
        else:
            LoadModel = AutoModelForCausalLM
        assert osp.exists(model_path) or len(model_path.split('/')) == 2

        device = self.explicit_device if self.explicit_device else 'auto'

        precision = {}
        if 'internlm-chat-7b' in model_path:
            precision = {'torch_dtype': torch.float16}
        elif 'internlm-chat-20b' in model_path:
            precision = {'torch_dtype': torch.bfloat16}

        self.tokenizer = AutoTokenizer.from_pretrained(model_path, trust_remote_code=True)
        cuda_devices = os.environ.get('CUDA_VISIBLE_DEVICES', '0')
        if ',' in cuda_devices:
            device_ids = [int(x) for x in cuda_devices.split(',')]
            _ = {i: i for i in range(len(device_ids))}
        else:
            _ = {'': 0}

        if 'llama' in self.model_path.lower():
            from lmdeploy import pipeline, GenerationConfig, TurbomindEngineConfig
            print(f"Loading model {model_path} with {num_gpu} GPUs")
            backend_config = TurbomindEngineConfig(tp=num_gpu)
            self.gen_config = GenerationConfig(max_new_tokens=256)
            model = pipeline(model_path, backend_config=backend_config)
        else:
            model = LoadModel.from_pretrained(model_path, trust_remote_code=True, device_map='cpu', **precision)
            model = model.eval()

            if device != 'cpu':
                model = model.to(f'cuda:{device}' if isinstance(device, int) else 'cuda')
            try:
                from transformers.generation import GenerationConfig
                model.generation_config = GenerationConfig.from_pretrained(
                    model_path, trust_remote_code=True, device_map=device)
            except Exception as err:
                self.logger.warning(f'{type(err)}: {err}')

            self.context_length = self._get_context_length_robust(model=model, model_path=model_path)

        torch.cuda.empty_cache()
        self.model = model
        self.answer_buffer = 192
        self.system_prompt = system_prompt
        for k, v in kwargs.items():
            self.logger.info(f'Following args will be used for generation (If not set specifically), {k}: {v}. ')
        self.kwargs = kwargs

    def generate_str(self, input, **kwargs):
        if 'baichuan' in self.model_path.lower():
            messages = []
            messages.append({'role': 'user', 'content': input})
            resp = self.model.chat(self.tokenizer, messages, **kwargs)
        elif 'vicuna' in self.model_path.lower():
            from fastchat.model import get_conversation_template
            conv = get_conversation_template('vicuna')
            conv.append_message(conv.roles[0], input)
            conv.append_message(conv.roles[1], None)
            prompt = conv.get_prompt()
            inputs = self.tokenizer([prompt], return_tensors='pt')
            if torch.cuda.is_available():
                for k in inputs:
                    inputs[k] = inputs[k].cuda()

            params = dict(do_sample=True, temperature=0.7, repetition_penalty=1.0, max_new_tokens=512)
            params.update(self.kwargs)
            params.update(kwargs)
            outputs = self.model.generate(**inputs, **params)
            resp = self.tokenizer.decode(
                outputs[0][len(inputs['input_ids'][0]):],
                skip_special_tokens=True,
                spaces_between_special_tokens=False)
        elif 'llama' in self.model_path.lower():
            prompt = [{'role': 'system', 'content': self.system_prompt}, {'role': 'user', 'content': input}]
            resp = self.model(prompt, gen_config=self.gen_config).text
        else:
            params = self.kwargs
            params.update(kwargs)
            resp, _ = self.model.chat(self.tokenizer, input, history=[], **params)

        return resp

    def length_ok(self, inputs):
        tot = len(self.tokenizer.encode(self.system_prompt)) if self.system_prompt is not None else 0
        for s in inputs:
            tot += len(self.tokenizer.encode(s))
        return tot + self.answer_buffer < self.context_length

    def generate_list(self, full_inputs, offset=0, **kwargs):
        assert isinstance(full_inputs, list)
        inputs = full_inputs[offset:]
        if not self.length_ok(inputs):
            return self.chat(full_inputs, offset + 1)

        model_path = self.model_path.lower()

        if sum([x in model_path for x in ['baichuan']]):
            input_msgs = []
            if self.system_prompt is not None:
                input_msgs.append(dict(role='user', content=self.system_prompt))
            if len(inputs):
                assert isinstance(inputs, list) and isinstance(inputs[0], str)
                roles = ['user', 'assistant'] if len(inputs) % 2 == 1 else ['assistant', 'user']
                roles = roles * len(inputs)
                for role, msg in zip(roles, inputs):
                    input_msgs.append(dict(role=role, content=msg))
            response = self.model.chat(self.tokenizer, input_msgs)
        elif sum([x in model_path for x in ['vicuna']]):
            from fastchat.model import get_conversation_template
            conv = get_conversation_template('vicuna')
            assert isinstance(inputs, list) and isinstance(inputs[0], str)
            if len(inputs) % 2 == 1:
                if self.system_prompt is not None:
                    conv.append_message(conv.roles[0], self.system_prompt)
                for i in range(len(inputs) // 2):
                    conv.append_message(conv.roles[0], inputs[2 * i])
                    conv.append_message(conv.roles[1], inputs[2 * i + 1])
            else:
                assert self.system_prompt is not None
                conv.append_message(conv.roles[0], self.system_prompt)
                conv.append_message(conv.roles[1], inputs[0])
                for i in range(len(inputs) // 2 - 1):
                    conv.append_message(conv.roles[0], inputs[2 * i + 1])
                    conv.append_message(conv.roles[1], inputs[2 * i + 2])
            conv.append_message(conv.roles[0], inputs[-1])
            conv.append_message(conv.roles[1], None)
            prompt = conv.get_prompt()
            inputs = self.tokenizer([prompt], return_tensors='pt')
            if torch.cuda.is_available():
                for k in inputs:
                    inputs[k] = inputs[k].cuda()

            params = dict(do_sample=True, temperature=0.7, repetition_penalty=1.0, max_new_tokens=512)
            params.update(self.kwargs)
            params.update(kwargs)

            outputs = self.model.generate(**inputs, **params)
            response = self.tokenizer.decode(
                outputs[0][len(inputs['input_ids'][0]):],
                skip_special_tokens=True,
                spaces_between_special_tokens=False)
            response = response.lstrip('\n')
        else:
            # The default option, support internlm, chatglm, qwen
            history, msg = [], None
            if len(inputs) % 2 == 1:
                if self.system_prompt is not None:
                    history = [(self.system_prompt, '')]
                for i in range(len(inputs) // 2):
                    history.append((inputs[2 * i], inputs[2 * i + 1]))
            else:
                assert self.system_prompt is not None
                history = [(self.system_prompt, inputs[0])]
                for i in range(len(inputs) // 2 - 1):
                    history.append((inputs[2 * i + 1], inputs[2 * i + 2]))
            msg = inputs[-1]

            params = self.kwargs
            params.update(kwargs)
            response, _ = self.model.chat(self.tokenizer, msg, history=history, **params)

        return response, offset

    def generate(self, inputs, **kwargs):
        if isinstance(inputs, str):
            return self.generate_str(inputs, **kwargs)
        elif isinstance(inputs, list):
            return self.generate_list(inputs, **kwargs)

import os
import time
import torch
from magic_pdf.config.constants import *
from magic_pdf.model.sub_modules.model_init import AtomModelSingleton
from magic_pdf.model.model_list import AtomicModel
from magic_pdf.utils.load_image import load_image, encode_image_base64
from transformers import LayoutLMv3ForTokenClassification
from loguru import logger
import yaml
from qwen_vl_utils import process_vision_info
from PIL import Image
from typing import List, Union
from openai import OpenAI
import asyncio


class MonkeyOCR:
    def __init__(self, config_path):
        current_file_path = os.path.abspath(__file__)

        current_dir = os.path.dirname(current_file_path)

        root_dir = os.path.dirname(current_dir)

        with open(config_path, 'r', encoding='utf-8') as f:
            self.configs = yaml.load(f, Loader=yaml.FullLoader)
        logger.info('using configs: {}'.format(self.configs))

        self.device = self.configs.get('device', 'cpu')
        logger.info('using device: {}'.format(self.device))

        bf16_supported = False
        if self.device.startswith("cuda"):
            bf16_supported = torch.cuda.is_bf16_supported()
        elif self.device.startswith("mps"):
            bf16_supported = True

        models_dir = self.configs.get(
            'models_dir', os.path.join(root_dir, 'model_weight')
        )

        logger.info('using models_dir: {}'.format(models_dir))
        if not os.path.exists(models_dir):
            raise FileNotFoundError(
                f"Model directory '{models_dir}' not found. "
                "Please run 'python download_model.py' to download the required models."
            )

        self.layout_config = self.configs.get('layout_config')
        self.layout_model_name = self.layout_config.get(
            'model', MODEL_NAME.DocLayout_YOLO
        )

        atom_model_manager = AtomModelSingleton()
        if self.layout_model_name == MODEL_NAME.DocLayout_YOLO:
            layout_model_path = os.path.join(models_dir, self.configs['weights'][self.layout_model_name])
            if not os.path.exists(layout_model_path):
                raise FileNotFoundError(
                    f"Layout model file not found at '{layout_model_path}'. "
                    "Please run 'python download_model.py' to download the required models."
                )
            self.layout_model = atom_model_manager.get_atom_model(
                atom_model_name=AtomicModel.Layout,
                layout_model_name=MODEL_NAME.DocLayout_YOLO,
                doclayout_yolo_weights=layout_model_path,
                device=self.device,
            )
        elif self.layout_model_name == MODEL_NAME.PaddleXLayoutModel:
            layout_model_path = None
            if self.layout_model_name in self.configs['weights']:
                layout_model_path = os.path.join(models_dir, self.configs['weights'][self.layout_model_name])
            self.layout_model = atom_model_manager.get_atom_model(
                atom_model_name=AtomicModel.Layout,
                layout_model_name=MODEL_NAME.PaddleXLayoutModel,
                paddlexlayout_model_dir=layout_model_path,
                device=self.device,
            )
        logger.info(f'layout model loaded: {self.layout_model_name}')


        layout_reader_config = self.layout_config.get('reader')
        self.layout_reader_name = layout_reader_config.get('name')
        if self.layout_reader_name == 'layoutreader':
            layoutreader_model_dir = os.path.join(models_dir, self.configs['weights'][self.layout_reader_name])
            if os.path.exists(layoutreader_model_dir):
                model = LayoutLMv3ForTokenClassification.from_pretrained(
                    layoutreader_model_dir
                )
            else:
                logger.warning(
                    'local layoutreader model not exists, use online model from huggingface'
                )
                model = LayoutLMv3ForTokenClassification.from_pretrained(
                    'hantian/layoutreader'
                )

            if bf16_supported:
                model.to(self.device).eval().bfloat16()
            else:
                model.to(self.device).eval()
        else:
            logger.error('model name not allow')
        self.layoutreader_model = model
        logger.info(f'layoutreader model loaded: {self.layout_reader_name}')

        self.chat_config = self.configs.get('chat_config', {})
        chat_backend = self.chat_config.get('backend', 'lmdeploy')
        chat_path = self.chat_config.get('weight_path', 'model_weight/Recognition')
        if chat_backend == 'lmdeploy':
            logger.info('Use LMDeploy as backend')
            self.chat_model = MonkeyChat_LMDeploy(chat_path)
        elif chat_backend == 'lmdeploy_queue':
            logger.info('Use LMDeploy Queue as backend')
            queue_config = self.chat_config.get('queue_config', {})
            self.chat_model = MonkeyChat_LMDeploy_queue(chat_path, **queue_config)
        elif chat_backend == 'vllm':
            logger.info('Use vLLM as backend')
            self.chat_model = MonkeyChat_vLLM(chat_path)
        elif chat_backend == 'vllm_queue':
            logger.info('Use vLLM Queue as backend')
            queue_config = self.chat_config.get('queue_config', {})
            self.chat_model = MonkeyChat_vLLM_queue(chat_path, **queue_config)
        elif chat_backend == 'transformers':
            logger.info('Use transformers as backend')
            batch_size = self.chat_config.get('batch_size', 5)
            self.chat_model = MonkeyChat_transformers(chat_path, batch_size, device=self.device)
        elif chat_backend == 'api':
            logger.info('Use API as backend')
            api_config = self.configs.get('api_config', {})
            if not api_config:
                raise ValueError("API configuration is required for API backend.")
            self.chat_model = MonkeyChat_OpenAIAPI(
                url=api_config.get('url'),
                model_name=api_config.get('model_name'),
                api_key=api_config.get('api_key', None)
            )
        else:
            logger.warning('Use LMDeploy as default backend')
            self.chat_model = MonkeyChat_LMDeploy(chat_path)
        logger.info(f'VLM loaded: {self.chat_model.model_name}')

class MonkeyChat_LMDeploy:
    def __init__(self, model_path, engine_config=None): 
        try:
            from lmdeploy import pipeline, GenerationConfig, PytorchEngineConfig, ChatTemplateConfig
        except ImportError:
            raise ImportError("LMDeploy is not installed. Please install it following: "
                              "https://github.com/Yuliang-Liu/MonkeyOCR/blob/main/docs/install_cuda.md "
                              "to use MonkeyChat_LMDeploy.")
        self.model_name = os.path.basename(model_path)
        self.engine_config = self._auto_config_dtype(engine_config, PytorchEngineConfig)
        self.pipe = pipeline(model_path, backend_config=self.engine_config, chat_template_config=ChatTemplateConfig('qwen2d5-vl'))
        self.gen_config=GenerationConfig(max_new_tokens=4096,do_sample=True,temperature=0,repetition_penalty=1.05)

    def _auto_config_dtype(self, engine_config=None, PytorchEngineConfig=None):
        if engine_config is None:
            engine_config = PytorchEngineConfig(session_len=10240)
        dtype = "bfloat16"
        if torch.cuda.is_available():
            device = torch.cuda.current_device()
            capability = torch.cuda.get_device_capability(device)
            sm_version = capability[0] * 10 + capability[1]  # e.g. sm75 = 7.5

            # use float16 if computing capability <= sm75 (7.5)
            if sm_version <= 75:
                dtype = "float16"
        engine_config.dtype = dtype
        return engine_config

    def batch_inference(self, images, questions):
        inputs = [(question, load_image(image, max_size=1600)) for image, question in zip(images, questions)]
        outputs = self.pipe(inputs, gen_config=self.gen_config)
        return [output.text for output in outputs]

class MonkeyChat_vLLM:
    def __init__(self, model_path):
        try:
            from vllm import LLM, SamplingParams
        except ImportError:
            raise ImportError("vLLM is not installed. Please install it following: "
                              "https://github.com/Yuliang-Liu/MonkeyOCR/blob/main/docs/install_cuda.md "
                               "to use MonkeyChat_vLLM.")
        self.model_name = os.path.basename(model_path)
        self.pipe = LLM(model=model_path,
                        max_seq_len_to_capture=10240,
                        mm_processor_kwargs={'use_fast': True},
                        gpu_memory_utilization=self._auto_gpu_mem_ratio(0.9))
        self.gen_config = SamplingParams(max_tokens=4096,temperature=0,repetition_penalty=1.05)

    def _auto_gpu_mem_ratio(self, ratio):
        mem_free, mem_total = torch.cuda.mem_get_info()
        ratio = ratio * mem_free / mem_total
        return ratio

    def batch_inference(self, images, questions):
        placeholder = "<|image_pad|>"
        prompts = [
            ("<|im_start|>system\nYou are a helpful assistant.<|im_end|>\n"
            f"<|im_start|>user\n<|vision_start|>{placeholder}<|vision_end|>"
            f"{question}<|im_end|>\n"
            "<|im_start|>assistant\n") for question in questions
        ]
        inputs = [{
            "prompt": prompts[i],
            "multi_modal_data": {
                "image": load_image(images[i], max_size=1600),
            }
        } for i in range(len(prompts))]
        outputs = self.pipe.generate(inputs, sampling_params=self.gen_config)
        return [o.outputs[0].text for o in outputs]

class MonkeyChat_transformers:
    def __init__(self, model_path: str, max_batch_size: int = 10, max_new_tokens=4096, device: str = None):
        try:
            from transformers import Qwen2_5_VLForConditionalGeneration, AutoProcessor
        except ImportError:
            raise ImportError("transformers is not installed. Please install it following: "
                              "https://github.com/Yuliang-Liu/MonkeyOCR/blob/main/docs/install_cuda.md "
                              "to use MonkeyChat_transformers.")
        self.model_name = os.path.basename(model_path)
        self.max_batch_size = max_batch_size
        self.max_new_tokens = max_new_tokens

        if device is None:
            self.device = 'cuda' if torch.cuda.is_available() else 'cpu'
        else:
            self.device = device

        bf16_supported = False
        if self.device.startswith("cuda"):
            bf16_supported = torch.cuda.is_bf16_supported()
        elif self.device.startswith("mps"):
            bf16_supported = True

        logger.info(f"Loading Qwen2.5VL model from: {model_path}")
        logger.info(f"Using device: {self.device}")
        logger.info(f"Max batch size: {self.max_batch_size}")

        try:
            self.model = Qwen2_5_VLForConditionalGeneration.from_pretrained(
                        model_path,
                        torch_dtype=torch.bfloat16 if bf16_supported else torch.float16,
                        attn_implementation="flash_attention_2" if self.device.startswith("cuda") else 'sdpa',
                        device_map=self.device,
                    )

            self.processor = AutoProcessor.from_pretrained(
                model_path,
                trust_remote_code=True
            )
            self.processor.tokenizer.padding_side = "left"

            self.model.eval()
            logger.info("Qwen2.5VL model loaded successfully")

        except Exception as e:
            logger.error(f"Failed to load model: {e}")
            raise e

    def prepare_messages(self, images: List[Union[str, Image.Image]], questions: List[str]) -> List[List[dict]]:
        if len(images) != len(questions):
            raise ValueError("Images and questions must have the same length")

        all_messages = []
        for image, question in zip(images, questions):
            messages = [
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image",
                            "image": load_image(image, max_size=1600),
                        },
                        {"type": "text", "text": question},
                    ],
                }
            ]
            all_messages.append(messages)

        return all_messages

    def batch_inference(self, images: List[Union[str, Image.Image]], questions: List[str]) -> List[str]:
        if len(images) != len(questions):
            raise ValueError("Images and questions must have the same length")

        results = []
        total_items = len(images)

        for i in range(0, total_items, self.max_batch_size):
            batch_end = min(i + self.max_batch_size, total_items)
            batch_images = images[i:batch_end]
            batch_questions = questions[i:batch_end]

            logger.info(f"Processing batch {i//self.max_batch_size + 1}/{(total_items-1)//self.max_batch_size + 1} "
                       f"(items {i+1}-{batch_end})")

            try:
                batch_results = self._process_batch(batch_images, batch_questions)
                results.extend(batch_results)
            except Exception as e:
                logger.error(f"Batch processing failed for items {i+1}-{batch_end}: {e}")
                logger.info("Falling back to single processing...")
                for img, q in zip(batch_images, batch_questions):
                    try:
                        single_result = self._process_single(img, q)
                        results.append(single_result)
                    except Exception as single_e:
                        logger.error(f"Single processing also failed: {single_e}")
                        results.append(f"Error: {str(single_e)}")

            if self.device == 'cuda':
                torch.cuda.empty_cache()

        return results

    def _process_batch(self, batch_images: List[Union[str, Image.Image]], batch_questions: List[str]) -> List[str]:
        all_messages = self.prepare_messages(batch_images, batch_questions)

        texts = []
        image_inputs = []

        for messages in all_messages:
            text = self.processor.apply_chat_template(
                messages, tokenize=False, add_generation_prompt=True
            )
            texts.append(text)

            image_inputs.append(process_vision_info(messages)[0])

        inputs = self.processor(
            text=texts,
            images=image_inputs,
            padding=True,
            return_tensors="pt",
        ).to(self.device)

        with torch.no_grad():
            generated_ids = self.model.generate(
                **inputs,
                max_new_tokens=self.max_new_tokens,
                do_sample=True,
                temperature=0.1,
                repetition_penalty=1.05,
                pad_token_id=self.processor.tokenizer.pad_token_id,
            )

        generated_ids_trimmed = [
            out_ids[len(in_ids):] for in_ids, out_ids in zip(inputs.input_ids, generated_ids)
        ]

        output_texts = self.processor.batch_decode(
            generated_ids_trimmed, skip_special_tokens=True, clean_up_tokenization_spaces=False
        )

        return [text.strip() for text in output_texts]

    def _process_single(self, image: Union[str, Image.Image], question: str) -> str:
        messages = [
            {
                "role": "user",
                "content": [
                    {
                        "type": "image",
                        "image": image,
                    },
                    {"type": "text", "text": question},
                ],
            }
        ]

        text = self.processor.apply_chat_template(
            messages, tokenize=False, add_generation_prompt=True
        )

        image_inputs, video_inputs = process_vision_info(messages)

        inputs = self.processor(
            text=[text],
            images=image_inputs,
            videos=video_inputs,
            padding=True,
            return_tensors="pt",
        ).to(self.device)

        with torch.no_grad():
            generated_ids = self.model.generate(
                **inputs,
                max_new_tokens=1024,
                do_sample=True,
                temperature=0.1,
                repetition_penalty=1.05,
            )

        generated_ids_trimmed = [
            out_ids[len(in_ids):] for in_ids, out_ids in zip(inputs.input_ids, generated_ids)
        ]

        output_text = self.processor.batch_decode(
            generated_ids_trimmed, skip_special_tokens=True, clean_up_tokenization_spaces=False
        )[0]

        return output_text.strip()

    def single_inference(self, image: Union[str, Image.Image], question: str) -> str:
        return self._process_single(image, question)

class MonkeyChat_OpenAIAPI:
    def __init__(self, url: str, model_name: str, api_key: str = None):
        self.model_name = model_name
        self.client = OpenAI(
            api_key=api_key,
            base_url=url
        )
        if not self.validate_connection():
            raise ValueError("Invalid API URL or API key. Please check your configuration.")

    def validate_connection(self) -> bool:
        """
        Validate the effectiveness of API URL and key
        """
        try:
            # Try to get model list to validate connection
            response = self.client.models.list()
            logger.info("API connection validation successful")
            return True
        except Exception as e:
            logger.error(f"API connection validation failed: {e}")
            return False

    def img2base64(self, image: Union[str, Image.Image]) -> tuple[str, str]:
        if hasattr(image, 'format') and image.format:
            img_format = image.format
        else:
            # Default to PNG if format is not specified
            img_format = "PNG"
        image = encode_image_base64(image)
        return image, img_format.lower()

    def batch_inference(self, images: List[Union[str, Image.Image]], questions: List[str]) -> List[str]:
        results = []
        for image, question in zip(images, questions):
            try:
                # Load and resize image
                image = load_image(image, max_size=1600)
                img, img_type = self.img2base64(image)

                messages=[{
                    "role": "user",
                    "content": [
                        {
                            "type": "input_image",
                            "image_url": f"data:image/{img_type};base64,{img}"
                        },
                        {
                            "type": "input_text", 
                            "text": question
                        }
                    ],
                }]
                response = self.client.chat.completions.create(
                    model=self.model_name,
                    messages=messages
                )
                results.append(response.choices[0].message.content)
            except Exception as e:
                results.append(f"Error: {e}")
        return results

class MonkeyChat_LMDeploy_queue:
    """
    Hybrid architecture: Combines synchronous batch processing with asynchronous concurrency for LMDeploy
    Designed for multi-user large-batch concurrent inference scenarios using LMDeploy backend

    Features:
    1. Uses request queue to collect requests from multiple users
    2. Dynamic batch merging to maximize GPU utilization
    3. Supports multi-user concurrency, each user can submit large batch tasks
    4. Achieves inference speed close to MonkeyChat_LMDeploy
    5. Uses LMDeploy's efficient pipeline for batch processing
    """

    def __init__(self, model_path, max_batch_size=32, queue_timeout=0.1, max_queue_size=1000, engine_config=None):
        try:
            from lmdeploy import pipeline, GenerationConfig, PytorchEngineConfig, ChatTemplateConfig
            import asyncio
            import threading
            from collections import deque
        except ImportError:
            raise ImportError("LMDeploy is not installed. Please install it following: "
                              "https://github.com/Yuliang-Liu/MonkeyOCR/blob/main/docs/install_cuda.md")

        self.model_name = os.path.basename(model_path)
        self.max_batch_size = max_batch_size
        self.queue_timeout = queue_timeout
        self.max_queue_size = max_queue_size

        # Clear GPU memory before initialization
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

        # Initialize LMDeploy pipeline (for efficient batch processing)
        self.engine_config = self._auto_config_dtype(engine_config, PytorchEngineConfig)
        self.pipe = pipeline(
            model_path, 
            backend_config=self.engine_config, 
            chat_template_config=ChatTemplateConfig('qwen2d5-vl')
        )

        self.gen_config = GenerationConfig(
            max_new_tokens=4096,
            do_sample=True,
            temperature=0,
            repetition_penalty=1.05
        )

        # Request queue and processing related
        self.request_queue = deque()
        self.result_futures = {}
        self.queue_lock = threading.Lock()
        self.processing = False
        self.shutdown_flag = False

        # Start background processing thread
        self.processor_thread = threading.Thread(target=self._background_processor, daemon=True)
        self.processor_thread.start()

        logger.info(f"LMDeploy MultiUser engine initialized for model: {self.model_name}")
        logger.info(f"Max batch size: {max_batch_size}, Queue timeout: {queue_timeout}s")

    def _auto_config_dtype(self, engine_config=None, PytorchEngineConfig=None):
        """Auto configure dtype based on GPU capability"""
        if engine_config is None:
            engine_config = PytorchEngineConfig(session_len=10240)
        dtype = "bfloat16"
        if torch.cuda.is_available():
            device = torch.cuda.current_device()
            capability = torch.cuda.get_device_capability(device)
            sm_version = capability[0] * 10 + capability[1]  # e.g. sm75 = 7.5

            # use float16 if computing capability <= sm75 (7.5)
            if sm_version <= 75:
                dtype = "float16"
        engine_config.dtype = dtype
        return engine_config

    def _background_processor(self):
        """Background thread: continuously process request queue"""
        import time

        while not self.shutdown_flag:
            try:
                # Collect a batch of requests
                batch_requests = self._collect_batch_requests()

                if batch_requests:
                    # Process batch requests
                    self._process_batch_requests(batch_requests)
                else:
                    # Sleep briefly when no requests
                    time.sleep(0.01)

            except Exception as e:
                logger.error(f"Background processor error: {e}")
                time.sleep(0.1)

    def _collect_batch_requests(self):
        """Collect a batch of requests, supports dynamic batch size"""
        import time

        batch_requests = []
        start_time = time.time()

        with self.queue_lock:
            # Collect requests until batch size reached or timeout
            while (len(batch_requests) < self.max_batch_size and 
                   time.time() - start_time < self.queue_timeout and
                   self.request_queue):

                request = self.request_queue.popleft()
                batch_requests.append(request)

        return batch_requests

    def _process_batch_requests(self, batch_requests):
        """Process batch requests using LMDeploy pipeline"""
        try:
            # Prepare batch inputs for LMDeploy
            inputs = []
            request_ids = []

            for request in batch_requests:
                request_id, image_path, question, future = request

                # Load image and prepare input tuple for LMDeploy
                image = load_image(image_path, max_size=1600)
                inputs.append((question, image))
                request_ids.append(request_id)

            # Batch inference using LMDeploy pipeline
            start_time = time.time()
            outputs = self.pipe(inputs, gen_config=self.gen_config)
            processing_time = time.time() - start_time

            logger.info(f"Processed batch of {len(batch_requests)} requests in {processing_time:.2f}s "
                       f"({len(batch_requests)/processing_time:.1f} req/s)")

            # Distribute results to corresponding futures
            for i, output in enumerate(outputs):
                request_id = request_ids[i]
                result_text = output.text

                # Get corresponding future from batch_requests and set result
                request = batch_requests[i]
                _, _, _, future = request

                try:
                    if not future.done():
                        # Need to set future result in correct event loop
                        if hasattr(future, '_loop') and future._loop is not None:
                            future._loop.call_soon_threadsafe(future.set_result, result_text)
                        else:
                            future.set_result(result_text)

                    # Clean from dictionary
                    if request_id in self.result_futures:
                        del self.result_futures[request_id]

                except Exception as e:
                    logger.error(f"Failed to set result for request {request_id}: {e}")
                    # Try to set error result
                    try:
                        if not future.done():
                            if hasattr(future, '_loop') and future._loop is not None:
                                future._loop.call_soon_threadsafe(future.set_result, f"Error: {str(e)}")
                            else:
                                future.set_result(f"Error: {str(e)}")
                    except Exception:
                        pass

        except Exception as e:
            logger.error(f"Batch processing failed: {e}")
            # Set all requests to error state
            for i, request in enumerate(batch_requests):
                request_id, _, _, future = request

                try:
                    if not future.done():
                        error_msg = f"Error: {str(e)}"
                        if hasattr(future, '_loop') and future._loop is not None:
                            future._loop.call_soon_threadsafe(future.set_result, error_msg)
                        else:
                            future.set_result(error_msg)

                    # Clean from dictionary
                    if request_id in self.result_futures:
                        del self.result_futures[request_id]

                except Exception as set_error:
                    logger.error(f"Failed to set error result for request {request_id}: {set_error}")

    async def async_single_inference(self, image: str, question: str) -> str:
        """Asynchronous single inference"""
        import asyncio
        import concurrent.futures
        import uuid

        request_id = f"lmdeploy_multiuser_{uuid.uuid4().hex[:8]}"

        # Create future to receive result
        loop = asyncio.get_event_loop()
        future = loop.create_future()

        # Add request to queue
        with self.queue_lock:
            if len(self.request_queue) >= self.max_queue_size:
                logger.warning(f"Request queue full, rejecting request {request_id}")
                return "Error: Request queue full"

            self.request_queue.append((request_id, image, question, future))
            self.result_futures[request_id] = future

        try:
            # Wait for result with timeout
            result = await asyncio.wait_for(future, timeout=300)
            return result
        except asyncio.TimeoutError:
            logger.error(f"Request {request_id} timed out")
            # Clean up timed out request
            with self.queue_lock:
                if request_id in self.result_futures:
                    del self.result_futures[request_id]
            return "Error: Request timeout"
        except asyncio.CancelledError:
            logger.info(f"Request {request_id} was cancelled")
            # Clean up cancelled request
            with self.queue_lock:
                if request_id in self.result_futures:
                    del self.result_futures[request_id]
            raise
        except Exception as e:
            logger.error(f"Request {request_id} failed with exception: {e}")
            # Clean up failed request
            with self.queue_lock:
                if request_id in self.result_futures:
                    del self.result_futures[request_id]
            return f"Error: {str(e)}"

    def single_inference(self, image: str, question: str) -> str:
        """Synchronous single inference (wraps async method)"""
        try:
            try:
                loop = asyncio.get_running_loop()
                # Already in async context, use thread executor
                import concurrent.futures

                def run_async_in_thread():
                    new_loop = asyncio.new_event_loop()
                    asyncio.set_event_loop(new_loop)
                    try:
                        return new_loop.run_until_complete(
                            self.async_single_inference(image, question)
                        )
                    finally:
                        new_loop.close()

                with concurrent.futures.ThreadPoolExecutor() as executor:
                    future = executor.submit(run_async_in_thread)
                    return future.result(timeout=300)

            except RuntimeError:
                # No running event loop
                return asyncio.run(self.async_single_inference(image, question))

        except Exception as e:
            logger.error(f"Single inference failed: {e}")
            return f"Error: {str(e)}"

    async def async_batch_inference(self, images: List[str], questions: List[str]) -> List[str]:
        """Asynchronous batch inference (decompose large batches into multiple concurrent requests)"""
        if len(images) != len(questions):
            raise ValueError("Images and questions must have the same length")

        # Create concurrent tasks
        tasks = []
        for image, question in zip(images, questions):
            task = self.async_single_inference(image, question)
            tasks.append(task)

        # Execute all tasks concurrently
        logger.info(f"Processing {len(tasks)} requests concurrently")
        results = await asyncio.gather(*tasks, return_exceptions=True)

        # Handle exception results
        processed_results = []
        for result in results:
            if isinstance(result, Exception):
                processed_results.append(f"Error: {str(result)}")
            else:
                processed_results.append(result)

        return processed_results

    def batch_inference(self, images: List[str], questions: List[str]) -> List[str]:
        """Synchronous batch inference"""
        try:
            try:
                loop = asyncio.get_running_loop()
                # Already in async context
                import concurrent.futures

                def run_async_in_thread():
                    new_loop = asyncio.new_event_loop()
                    asyncio.set_event_loop(new_loop)
                    try:
                        return new_loop.run_until_complete(
                            self.async_batch_inference(images, questions)
                        )
                    finally:
                        new_loop.close()

                with concurrent.futures.ThreadPoolExecutor() as executor:
                    future = executor.submit(run_async_in_thread)
                    return future.result(timeout=600)

            except RuntimeError:
                # No running event loop
                return asyncio.run(self.async_batch_inference(images, questions))

        except Exception as e:
            logger.error(f"Batch inference failed: {e}")
            return [f"Error: {str(e)}"] * len(images)

    def get_queue_status(self):
        """Get queue status (for monitoring)"""
        with self.queue_lock:
            return {
                "queue_size": len(self.request_queue),
                "pending_results": len(self.result_futures),
                "max_queue_size": self.max_queue_size,
                "processing": self.processing,
                "processor_thread_alive": self.processor_thread.is_alive(),
                "shutdown_flag": self.shutdown_flag
            }

    def shutdown(self):
        """Shutdown service"""
        self.shutdown_flag = True

        # Wait for background thread to finish
        if self.processor_thread.is_alive():
            self.processor_thread.join(timeout=5)

        # Clean up unfinished requests
        with self.queue_lock:
            for request_id, future in self.result_futures.items():
                if not future.done():
                    future.set_result("Error: Service shutdown")
            self.result_futures.clear()
            self.request_queue.clear()

        # Clean up pipeline and GPU memory
        try:
            if hasattr(self, 'pipe') and self.pipe is not None:
                del self.pipe
            if torch.cuda.is_available():
                torch.cuda.empty_cache()
                torch.cuda.synchronize()
        except Exception as e:
            logger.warning(f"Error during cleanup: {e}")

        logger.info("LMDeploy MultiUser engine shutdown completed")

    def __del__(self):
        """Destructor"""
        try:
            self.shutdown()
        except Exception:
            pass

class MonkeyChat_vLLM_queue:
    """
    Hybrid architecture: Combines synchronous batch processing with asynchronous concurrency
    Designed for multi-user large-batch concurrent inference scenarios

    Features:
    1. Uses request queue to collect requests from multiple users
    2. Dynamic batch merging to maximize GPU utilization
    3. Supports multi-user concurrency, each user can submit large batch tasks
    4. Achieves inference speed close to MonkeyChat_vLLM
    """

    def __init__(self, model_path, max_batch_size=64, queue_timeout=0.1, max_queue_size=1000):
        try:
            from vllm import LLM, SamplingParams
            import asyncio
            import threading
            from collections import deque
        except ImportError:
            raise ImportError("vLLM is not installed. Please install it following: "
                              "https://github.com/Yuliang-Liu/MonkeyOCR/blob/main/docs/install_cuda.md")

        self.model_name = os.path.basename(model_path)
        self.max_batch_size = max_batch_size
        self.queue_timeout = queue_timeout
        self.max_queue_size = max_queue_size

        # Initialize synchronous vLLM engine (for efficient batch processing)
        self.engine = LLM(
            model=model_path,
            max_seq_len_to_capture=10240,
            mm_processor_kwargs={'use_fast': True},
            gpu_memory_utilization=self._auto_gpu_mem_ratio(0.9),
            max_num_seqs=max_batch_size * 2,  # Allow larger sequence numbers
        )

        self.gen_config = SamplingParams(
            max_tokens=4096, 
            temperature=0, 
            repetition_penalty=1.05
        )

        # Request queue and processing related
        self.request_queue = deque()
        self.result_futures = {}
        self.queue_lock = threading.Lock()
        self.processing = False
        self.shutdown_flag = False

        # Start background processing thread
        self.processor_thread = threading.Thread(target=self._background_processor, daemon=True)
        self.processor_thread.start()

        logger.info(f"vLLM MultiUser engine initialized for model: {self.model_name}")
        logger.info(f"Max batch size: {max_batch_size}, Queue timeout: {queue_timeout}s")

    def _auto_gpu_mem_ratio(self, ratio):
        mem_free, mem_total = torch.cuda.mem_get_info()
        ratio = ratio * mem_free / mem_total
        return ratio

    def _background_processor(self):
        """Background thread: continuously process request queue"""
        import time

        while not self.shutdown_flag:
            try:
                # Collect a batch of requests
                batch_requests = self._collect_batch_requests()

                if batch_requests:
                    # Process batch requests
                    self._process_batch_requests(batch_requests)
                else:
                    # Sleep briefly when no requests
                    time.sleep(0.01)

            except Exception as e:
                logger.error(f"Background processor error: {e}")
                time.sleep(0.1)

    def _collect_batch_requests(self):
        """Collect a batch of requests, supports dynamic batch size"""
        import time

        batch_requests = []
        start_time = time.time()

        with self.queue_lock:
            # Collect requests until batch size reached or timeout
            while (len(batch_requests) < self.max_batch_size and 
                   time.time() - start_time < self.queue_timeout and
                   self.request_queue):

                request = self.request_queue.popleft()
                batch_requests.append(request)

        return batch_requests

    def _process_batch_requests(self, batch_requests):
        """Process batch requests using synchronous engine"""
        try:
            # Prepare batch inputs
            placeholder = "<|image_pad|>"
            inputs = []
            request_ids = []

            for request in batch_requests:
                request_id, image_path, question, future = request

                prompt = (
                    "<|im_start|>system\nYou are a helpful assistant.<|im_end|>\n"
                    f"<|im_start|>user\n<|vision_start|>{placeholder}<|vision_end|>"
                    f"{question}<|im_end|>\n"
                    "<|im_start|>assistant\n"
                )

                inputs.append({
                    "prompt": prompt,
                    "multi_modal_data": {
                        "image": load_image(image_path, max_size=1600),
                    }
                })
                request_ids.append(request_id)

            # Batch inference (using high-efficiency batch processing of synchronous engine)
            start_time = time.time()
            outputs = self.engine.generate(inputs, sampling_params=self.gen_config)
            processing_time = time.time() - start_time

            logger.info(f"Processed batch of {len(batch_requests)} requests in {processing_time:.2f}s "
                       f"({len(batch_requests)/processing_time:.1f} req/s)")

            # Distribute results to corresponding futures
            for i, output in enumerate(outputs):
                request_id = request_ids[i]
                result_text = output.outputs[0].text

                # Get corresponding future from batch_requests and set result
                request = batch_requests[i]
                _, _, _, future = request

                try:
                    if not future.done():
                        # Need to set future result in correct event loop
                        if hasattr(future, '_loop') and future._loop is not None:
                            future._loop.call_soon_threadsafe(future.set_result, result_text)
                        else:
                            future.set_result(result_text)

                    # Clean from dictionary
                    if request_id in self.result_futures:
                        del self.result_futures[request_id]

                except Exception as e:
                    logger.error(f"Failed to set result for request {request_id}: {e}")
                    # Try to set error result
                    try:
                        if not future.done():
                            if hasattr(future, '_loop') and future._loop is not None:
                                future._loop.call_soon_threadsafe(future.set_result, f"Error: {str(e)}")
                            else:
                                future.set_result(f"Error: {str(e)}")
                    except Exception:
                        pass

        except Exception as e:
            logger.error(f"Batch processing failed: {e}")
            # Set all requests to error state
            for i, request in enumerate(batch_requests):
                request_id, _, _, future = request

                try:
                    if not future.done():
                        error_msg = f"Error: {str(e)}"
                        if hasattr(future, '_loop') and future._loop is not None:
                            future._loop.call_soon_threadsafe(future.set_result, error_msg)
                        else:
                            future.set_result(error_msg)

                    # Clean from dictionary
                    if request_id in self.result_futures:
                        del self.result_futures[request_id]

                except Exception as set_error:
                    logger.error(f"Failed to set error result for request {request_id}: {set_error}")

